import { tracked } from "@glimmer/tracking";
import { meta } from "@ember/-internals/meta";
import { isArray } from "@ember/array";
import {
  defineProperty,
  get,
  getProperties,
  notifyPropertyChange,
  set,
} from "@ember/object";
import { dependentKeyCompat } from "@ember/object/compat";
import ObjectProxy from "@ember/object/proxy";

const hasOwnProp = Object.prototype.hasOwnProperty;

function isEmpty(obj) {
  for (const key in obj) {
    if (hasOwnProp.call(obj, key)) {
      return false;
    }
  }
  return true;
}

/**
 * An `ObjectProxy` which holds writes in a buffer until they are applied to the
 * underlying `content`, so edits can be discarded without touching the original.
 */
export default class BufferedProxy extends ObjectProxy {
  @tracked hasBufferedChanges;

  init() {
    this.initializeBuffer();
    set(this, "hasBufferedChanges", false);
    super.init(...arguments);
  }

  @dependentKeyCompat
  get hasChanges() {
    return this.hasBufferedChanges;
  }

  initializeBuffer(onlyTheseKeys) {
    if (isArray(onlyTheseKeys) && !isEmpty(onlyTheseKeys)) {
      onlyTheseKeys.forEach((key) => delete this.buffer[key]);
    } else {
      set(this, "buffer", Object.create(null));
    }
  }

  unknownProperty(key) {
    const buffer = get(this, "buffer");

    return hasOwnProp.call(buffer, key)
      ? buffer[key]
      : super.unknownProperty(key);
  }

  setUnknownProperty(key, value) {
    const m = meta(this);

    // A prototype or still-initializing object has no buffer to delegate to.
    if (m.proto === this || (m.isInitializing && m.isInitializing())) {
      defineProperty(this, key, null, value);
      return value;
    }

    const { buffer, content } = getProperties(this, ["buffer", "content"]);
    const current = content == null ? undefined : get(content, key);
    const previous = hasOwnProp.call(buffer, key) ? buffer[key] : current;

    if (previous === value) {
      return;
    }

    if (current === value) {
      delete buffer[key];
      if (isEmpty(buffer)) {
        set(this, "hasBufferedChanges", false);
      }
    } else {
      buffer[key] = value;
      set(this, "hasBufferedChanges", true);
    }

    notifyPropertyChange(this, key);

    return value;
  }

  applyBufferedChanges(onlyTheseKeys) {
    const { buffer, content } = getProperties(this, ["buffer", "content"]);

    for (const key of Object.keys(buffer)) {
      if (isArray(onlyTheseKeys) && !onlyTheseKeys.includes(key)) {
        continue;
      }

      set(content, key, buffer[key]);
    }

    this.initializeBuffer(onlyTheseKeys);

    if (isEmpty(get(this, "buffer"))) {
      set(this, "hasBufferedChanges", false);
    }
  }

  discardBufferedChanges(onlyTheseKeys) {
    const buffer = get(this, "buffer");

    this.initializeBuffer(onlyTheseKeys);

    for (const key of Object.keys(buffer)) {
      if (isArray(onlyTheseKeys) && !onlyTheseKeys.includes(key)) {
        continue;
      }

      notifyPropertyChange(this, key);
    }

    if (isEmpty(get(this, "buffer"))) {
      set(this, "hasBufferedChanges", false);
    }
  }

  applyChanges(...args) {
    return this.applyBufferedChanges(...args);
  }

  discardChanges(...args) {
    return this.discardBufferedChanges(...args);
  }

  /** Whether a single key differs from `content`, rather than the whole buffer. */
  hasChanged(key) {
    const { buffer, content } = getProperties(this, ["buffer", "content"]);

    if (typeof key !== "string" || typeof get(buffer, key) === "undefined") {
      return false;
    }

    return get(buffer, key) !== get(content, key);
  }
}
import DButton from "discourse/ui-kit/d-button";
import { i18n } from "discourse-i18n";

const DModalCancel = <template>
  <DButton
    class="btn-flat d-modal-cancel"
    @action={{@close}}
    @translatedLabel={{i18n "cancel"}}
  />
</template>;

export default DModalCancel;
/* eslint-disable ember/no-classic-components, ember/require-tagless-components */
/* eslint-disable ember/no-classic-classes */
import { MUTABLE_CELL } from "@ember/-internals/views";
import Component from "@ember/component";
import { computed, get, set } from "@ember/object";

const inputTypes = Object.create(null);
function canSetTypeOfInput(type) {
  if (type in inputTypes) {
    return inputTypes[type];
  }

  let inputTypeTestElement = document.createElement("input");

  try {
    inputTypeTestElement.type = type;
  } catch {
    // ignored
  }

  return (inputTypes[type] = inputTypeTestElement.type === type);
}

const KEY_EVENTS = {
  Enter: "insertNewline",
  Escape: "cancel",
};

function sendAction(eventName, view, event) {
  let action = get(view, `attrs.${eventName}`);
  if (
    action !== null &&
    typeof action === "object" &&
    action[MUTABLE_CELL] === true
  ) {
    action = action.value;
  }

  if (action === undefined) {
    action = get(view, eventName);
  }

  let value = view.value;

  if (typeof action === "function") {
    action(value, event);
  }

  if (action && !view.bubbles) {
    event.stopPropagation();
  }
}

const TextField = Component.extend({
  classNames: ["ember-text-field"],
  tagName: "input",

  attributeBindings: [
    "accept",
    "autocomplete",
    "autosave",
    "dir",
    "formaction",
    "formenctype",
    "formmethod",
    "formnovalidate",
    "formtarget",
    "height",
    "inputmode",
    "lang",
    "list",
    "type", // needs to be before min and max. See #15675
    "max",
    "min",
    "multiple",
    "name",
    "pattern",
    "size",
    "step",
    "value",
    "width",
    "autocapitalize",
    "autocorrect",
    "autofocus",
    "disabled",
    "form",
    "maxlength",
    "minlength",
    "readonly",
    "required",
    "selectionDirection",
    "spellcheck",
    "tabindex",
    "title",
  ],

  value: "",

  type: computed({
    get() {
      return "text";
    },

    set(_key, value) {
      let type = "text";

      if (canSetTypeOfInput(value)) {
        type = value;
      }

      return type;
    },
  }),

  /** @type {string | number | null | undefined} */
  size: null,

  /** @type {string | null | undefined} */
  pattern: null,

  /** @type {string | number | null | undefined} */
  min: null,

  /** @type {string | number | null | undefined} */
  max: null,

  /** @type {string | null | undefined} */
  placeholder: null,
  disabled: false,
  /** @type {string | number | null | undefined} */
  maxlength: null,

  init() {
    this._super(...arguments);
    this.on("paste", this, this._elementValueDidChange);
    this.on("cut", this, this._elementValueDidChange);
    this.on("input", this, this._elementValueDidChange);
  },

  bubbles: false,

  interpretKeyEvents(event) {
    let method = KEY_EVENTS[event.key];

    this._elementValueDidChange();
    if (method) {
      return this[method](event);
    }
  },

  _elementValueDidChange() {
    set(this, "value", this.element.value);
  },

  change(event) {
    this._elementValueDidChange(event);
  },

  insertNewline(event) {
    sendAction("enter", this, event);
    sendAction("insert-newline", this, event);
  },

  cancel(event) {
    sendAction("escape-press", this, event);
  },

  focusIn(event) {
    sendAction("focus-in", this, event);
  },

  focusOut(event) {
    this._elementValueDidChange(event);
    sendAction("focus-out", this, event);
  },

  keyPress(event) {
    sendAction("key-press", this, event);
  },

  keyUp(event) {
    this.interpretKeyEvents(event);
    sendAction("key-up", this, event);
  },

  keyDown(event) {
    sendAction("key-down", this, event);
  },
});

TextField.toString = () => "@ember/component/text-field";

export default TextField;
import { computed } from "@ember/object";
import { cancel, next } from "@ember/runloop";
import { attributeBindings } from "@ember-decorators/component";
import TextField from "discourse/components/ember-text-field";
import discourseDebounce from "discourse/lib/debounce";
import { siteDir } from "discourse/lib/text-direction";
import { i18n } from "discourse-i18n";

const DEBOUNCE_MS = 500;

@attributeBindings(
  "autocorrect",
  "autocapitalize",
  "autofocus",
  "enterkeyhint",
  "maxLength",
  "dir",
  "aria-label",
  "aria-controls",
  "resolvedPlaceholder:placeholder"
)
export default class DTextField extends TextField {
  /** @type {string | number | null | undefined} */
  _prevValue = null;

  /** @type {import("@ember/runloop").Timer | null} */
  _timer = null;

  @computed("siteSettings.support_mixed_text_direction", "value")
  get dir() {
    if (this.siteSettings.support_mixed_text_direction) {
      const value = this.value?.toString() || "";

      if (value) {
        return "auto";
      }

      return siteDir();
    }
  }

  /**
   * The bound `placeholder` attribute, derived from both arguments. This is
   * a separate computed rather than a setter on `placeholder`: Ember caches
   * what a computed setter returns at assignment time, so the result would
   * depend on which argument the caller passes first.
   */
  @computed("placeholder", "placeholderKey")
  get resolvedPlaceholder() {
    if (this.placeholder) {
      return this.placeholder;
    }
    return this.placeholderKey ? i18n(this.placeholderKey) : "";
  }

  didReceiveAttrs() {
    super.didReceiveAttrs(...arguments);

    this._prevValue = this.value;
  }

  didUpdateAttrs() {
    super.didUpdateAttrs(...arguments);

    if (this._prevValue !== this.value) {
      if (this.onChangeImmediate) {
        next(() => this.onChangeImmediate(this.value));
      }
      if (this.onChange) {
        cancel(this._timer);
        this._timer = discourseDebounce(
          this,
          this._debouncedChange,
          DEBOUNCE_MS
        );
      }
    }
  }

  willDestroyElement() {
    super.willDestroyElement(...arguments);
    cancel(this._timer);
  }

  _debouncedChange() {
    next(() => this.onChange(this.value));
  }
}
import Component from "@glimmer/component";
import { modifier } from "ember-modifier";
import DOverflowControls, {
  type DOverflowControlsBag,
} from "discourse/ui-kit/d-overflow-controls";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";

const ACTIVE_ITEM = "a.active, button.active";

const EDGE_CLASSES = {
  left: "horizontal-overflow-nav__scroll-left",
  right: "horizontal-overflow-nav__scroll-right",
};

interface DHorizontalOverflowNavSignature {
  Args: {
    /** The accessible name of the navigation landmark, already translated. */
    ariaLabel?: string;

    /** Extra class(es) added to the list element. */
    className?: string;
  };

  /** The list element. Consumers yield its `li` children. */
  Element: HTMLUListElement;

  Blocks: {
    /** The `li` items of the list. */
    default: [];
  };
}

/**
 * A navigation bar whose pills scroll sideways when they outgrow it, built
 * on `DOverflowControls`: edge fades, chevrons, press-and-hold, and the
 * active item revealed on mount.
 *
 * Consumers yield bare `li` elements. The list keeps the `nav-pills`
 * styling contract and receives every attribute.
 */
export default class DHorizontalOverflowNav extends Component<DHorizontalOverflowNavSignature> {
  /**
   * Reveals the active item once, centered in the strip. When no active
   * item exists on mount, as in a portal-filled list, it watches the list
   * and reveals the first one that appears.
   */
  revealActive = modifier(
    (list: HTMLElement, [strip]: [strip: DOverflowControlsBag]) => {
      const reveal = () => {
        const active = list.querySelector<HTMLElement>(ACTIVE_ITEM);
        if (!active) {
          return false;
        }
        strip.reveal(active, { align: "center" });
        return true;
      };

      if (reveal()) {
        return;
      }

      const observer = new MutationObserver(() => {
        if (reveal()) {
          observer.disconnect();
        }
      });
      observer.observe(list, { childList: true, subtree: true });

      return () => observer.disconnect();
    }
  );

  <template>
    <nav aria-label={{@ariaLabel}} class="horizontal-overflow-nav">
      <DOverflowControls
        @axis="horizontal"
        @edgeButtonClasses={{EDGE_CLASSES}}
        @ownedScroller={{true}}
        @wrapperClass="horizontal-overflow-nav__controls"
        as |strip|
      >
        <ul
          class={{dConcatClass "nav-pills action-list" @className}}
          ...attributes
          {{strip.scroller}}
          {{this.revealActive strip}}
        >
          {{yield}}
        </ul>
      </DOverflowControls>
    </nav>
  </template>
}
import Component from "@glimmer/component";
import { concat } from "@ember/helper";
import { trustHTML } from "@ember/template";
import { convertIconClass } from "discourse/lib/icon-library";
import { escapeExpression } from "discourse/lib/utilities";
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import dIcon from "discourse/ui-kit/helpers/d-icon";

export default class DAvatarFlair extends Component {
  get icon() {
    return convertIconClass(this.args.flairUrl);
  }

  get isIcon() {
    return this.args.flairUrl && !this.args.flairUrl.includes("/");
  }

  get style() {
    const css = [];

    if (!this.isIcon) {
      css.push(
        "background-image: url(" + escapeExpression(this.args.flairUrl) + ")"
      );
    }

    if (this.args.flairBgColor) {
      css.push(
        "background-color: #" + escapeExpression(this.args.flairBgColor)
      );
    }

    if (this.args.flairColor) {
      css.push("color: #" + escapeExpression(this.args.flairColor));
    }

    return css.length > 0 ? trustHTML(css.join("; ")) : null;
  }

  get title() {
    return this.args.flairName;
  }

  <template>
    <div
      class={{dConcatClass
        "avatar-flair"
        (concat "avatar-flair-" @flairName)
        (if @flairBgColor "rounded")
        (unless this.isIcon "avatar-flair-image")
      }}
      style={{this.style}}
      title={{this.title}}
      ...attributes
    >
      {{#if this.isIcon}}
        {{dIcon this.icon}}
      {{/if}}
    </div>
  </template>
}
import { trustHTML } from "@ember/template";
import { number as numberFormatter } from "discourse/lib/formatter";
import { escapeExpression } from "discourse/lib/utilities";
import I18n, { i18n } from "discourse-i18n";

export default function dNumber(orig, params = {}) {
  orig = Math.round(parseFloat(orig));
  if (isNaN(orig)) {
    orig = 0;
  }

  let title = I18n.toNumber(orig, { precision: 0 });
  if (params.numberKey) {
    title = i18n(params.numberKey, {
      number: title,
      count: parseInt(orig, 10),
    });
  }

  let classNames = "number";
  if (params["class"]) {
    classNames += " " + params["class"];
  }

  let result = "<span class='" + classNames + "'";
  let addTitle = params.noTitle ? false : true;

  // Round off the thousands to one decimal place
  const n = numberFormatter(orig, { maxDisplay: params.maxDisplay });
  if (n.toString() !== title.toString() && addTitle) {
    result += " title='" + escapeExpression(title) + "'";
  }
  if (params.ariaLabel) {
    const ariaLabel = escapeExpression(params.ariaLabel);
    result += ` aria-label='${ariaLabel}'`;
  }

  result += ">" + n + "</span>";

  return trustHTML(result);
}
import dConcatClass from "discourse/ui-kit/helpers/d-concat-class";
import { i18n } from "discourse-i18n";

const DConditionalLoadingSection = <template>
  <div
    class={{dConcatClass
      "conditional-loading-section"
      (if @isLoading "is-loading")
    }}
    ...attributes
  >
    {{#if @isLoading}}
      <span class="title">{{or
          @title
          (i18n "conditional_loading_section.loading")
        }}</span>
      <div class="spinner {{@size}}"></div>
    {{else}}
      {{yield}}
    {{/if}}
  </div>
</template>;

export default DConditionalLoadingSection;
import { applyInlineOneboxes } from "pretty-text/inline-oneboxer";
import { load } from "pretty-text/oneboxer";

export function loadOneboxes(
  container,
  ajax,
  topicId,
  categoryId,
  maxOneboxes,
  refresh,
  offline,
  onLoad
) {
  const oneboxes = {};
  const inlineOneboxes = {};

  // Oneboxes = `a.onebox` -> `a.onebox-loading` -> `aside.onebox`
  // Inline Oneboxes = `a.inline-onebox-loading` -> `a.inline-onebox`

  let loadedOneboxes = 0;

  container
    .querySelectorAll("a.onebox, a.inline-onebox-loading")
    .forEach((link) => {
      const isInline = link.classList.contains("inline-onebox-loading");

      // maps URLs to their link elements
      const map = isInline ? inlineOneboxes : oneboxes;

      if (loadedOneboxes < maxOneboxes) {
        if (map[link.href] === undefined) {
          map[link.href] = [];
          loadedOneboxes++;
        }
        map[link.href].push(link);
      } else {
        if (map[link.href] !== undefined) {
          map[link.href].push(link);
        } else if (isInline) {
          link.classList.remove("inline-onebox-loading");
        }
      }
    });

  if (Object.keys(oneboxes).length > 0) {
    _loadOneboxes({
      oneboxes,
      ajax,
      topicId,
      categoryId,
      refresh,
      offline,
      onLoad,
    });
  }

  if (Object.keys(inlineOneboxes).length > 0) {
    _loadInlineOneboxes(inlineOneboxes, ajax, topicId, categoryId, onLoad);
  }

  return Object.keys(oneboxes).length + Object.keys(inlineOneboxes).length;
}

function _loadInlineOneboxes(inline, ajax, topicId, categoryId, onLoad) {
  applyInlineOneboxes(inline, ajax, { categoryId, topicId, onLoad });
}

function _loadOneboxes({
  oneboxes,
  ajax,
  topicId,
  categoryId,
  refresh,
  offline,
  onLoad,
}) {
  Object.values(oneboxes).forEach((onebox) => {
    onebox.forEach((elem) => {
      load({
        elem,
        ajax,
        categoryId,
        topicId,
        refresh,
        offline,
        onResolve: onLoad,
      });
    });
  });
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import didUpdate from "@ember/render-modifiers/modifiers/did-update";
import { service } from "@ember/service";
import { waitForPromise } from "@ember/test-waiters";
import { resolveAllShortUrls } from "pretty-text/upload-short-url";
import { ajax } from "discourse/lib/ajax";
import { loadOneboxes } from "discourse/lib/load-oneboxes";
import { cook } from "discourse/lib/text";

export default class DCookText extends Component {
  @service siteSettings;

  /** @type {import("@ember/template").TrustedHTML | null} */
  @tracked cooked = null;

  constructor(owner, args) {
    super(owner, args);
    this.loadCookedText();
  }

  @action
  async loadCookedText() {
    const rawText = this.args.rawText;
    const cooked = await waitForPromise(cook(rawText));
    if (this.isDestroying) {
      return;
    }
    if (this.args.rawText !== rawText) {
      return;
    }
    this.cooked = cooked;
  }

  @action
  calculateOffsetHeight(element) {
    if (!this.args.onOffsetHeightCalculated) {
      return;
    }

    return this.args.onOffsetHeightCalculated(element?.offsetHeight);
  }

  @action
  buildOneboxes(element) {
    if (this.args.paintOneboxes && this.cooked !== null) {
      loadOneboxes(
        element,
        ajax,
        this.args.topicId,
        this.args.categoryId,
        this.siteSettings.max_oneboxes_per_post,
        false // refresh
      );
    }
  }

  @action
  resolveShortUrls(element) {
    resolveAllShortUrls(ajax, this.siteSettings, element, this.args.opts);
  }

  <template>
    <div
      ...attributes
      {{didUpdate this.buildOneboxes this.cooked}}
      {{didUpdate this.resolveShortUrls this.cooked}}
      {{didUpdate this.calculateOffsetHeight this.cooked}}
      {{didUpdate this.loadCookedText @rawText}}
    >
      {{this.cooked}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { tracked } from "@glimmer/tracking";
import { action } from "@ember/object";
import { modifier } from "ember-modifier";
import discourseDebounce from "discourse/lib/debounce";
import { bind } from "discourse/lib/decorators";
import { clipboardCopy } from "discourse/lib/utilities";
import DButton from "discourse/ui-kit/d-button";

export default class DCopyButton extends Component {
  @tracked showCopied = false;

  watchExternalCopy = modifier((_, [isCopied]) => {
    if (isCopied && !this._wasCopied) {
      this._showCopied();
    }

    this._wasCopied = isCopied;
  });

  get copyIcon() {
    return this.showCopied ? "check" : this.args.icon || "copy";
  }

  get copyClass() {
    const baseClass = this.args.copyClass || "btn-primary";
    return this.showCopied ? `${baseClass} ok` : baseClass;
  }

  get copyTranslatedLabel() {
    return this.showCopied
      ? this.args.translatedLabelAfterCopy
      : this.args.translatedLabel;
  }

  get announcement() {
    return this.showCopied ? this.args.translatedLabelAfterCopy : "";
  }

  @action
  async copy() {
    let value = this.args.value;

    if (value === undefined) {
      if (!this.args.selector) {
        return;
      }

      const target = document.querySelector(this.args.selector);
      if (!target) {
        return;
      }

      value = target.value ?? target.textContent;
    }

    if (value == null) {
      return;
    }

    try {
      await clipboardCopy(value);
      this.args.copied?.();
      this._showCopied();
    } catch {}
  }

  _showCopied() {
    this.showCopied = true;

    discourseDebounce(this._restoreButton, 3000);
  }

  @bind
  _restoreButton() {
    if (this.isDestroying) {
      return;
    }

    this.showCopied = false;
  }

  <template>
    <DButton
      class="copy-button {{this.copyClass}}"
      @action={{this.copy}}
      @ariaLabel={{@ariaLabel}}
      @icon={{this.copyIcon}}
      @translatedLabel={{this.copyTranslatedLabel}}
    />
    <span
      aria-live="polite"
      class="sr-only"
      {{this.watchExternalCopy @isCopied}}
    >{{this.announcement}}</span>
  </template>
}
/* eslint-disable ember/no-classic-components, ember/require-tagless-components */
import Component, { Input } from "@ember/component";
import { on } from "@ember/modifier";
import { action, computed } from "@ember/object";
import { schedule } from "@ember/runloop";
import { waitForPromise } from "@ember/test-waiters";
import { classNames } from "@ember-decorators/component";
import { on as onEvent } from "@ember-decorators/object";
import { Promise } from "rsvp";
import { i18n } from "discourse-i18n";

/**
 * @typedef {Object} DateInputPicker
 * @property {(date: import("moment").Moment | Date | string | null, preventOnSelect?: boolean) => void} setDate
 * @property {(date: import("moment").Moment | Date | string | null | undefined) => void} setMinDate
 * @property {() => void} hide
 * @property {() => void} destroy
 */

function isInputDateSupported() {
  const input = document.createElement("input");
  const value = "a";
  input.setAttribute("type", "date");
  input.setAttribute("value", value);
  return input.value !== value;
}

@classNames("d-date-input")
export default class DDateInput extends Component {
  /** @type {import("moment").Moment | Date | string | null | undefined} */
  date = null;
  useNativePicker = isInputDateSupported();

  /** @type {DateInputPicker | null} */
  _picker = null;

  @computed("_placeholder")
  get placeholder() {
    return this._placeholder || i18n("dates.placeholder");
  }

  set placeholder(value) {
    this.set("_placeholder", value);
  }

  @computed("site.mobileView")
  get inputType() {
    return this.useNativePicker ? "date" : "text";
  }

