export function adjustedRangeEnd(from, to, { dateOnly = false } = {}) {
  if (!from || !to) {
    return to;
  }

  if (dateOnly) {
    return to.isBefore(from, "day") ? from.clone() : to;
  }

  if (to.isBefore(from) || to.isSame(from)) {
    return from.clone().add(1, "hour");
  }

  return to;
}

export function parseCustomDatetime(
  date,
  time,
  currentTimezone,
  parseTimezone = null
) {
