export default class FormTemplateChooser extends MultiSelectComponent {
  init() {
    super.init(...arguments);
    this.triggerSearch();
  }

  @computed("templates")
  get content() {
    return this.templates;
  }

  didUpdateAttrs() {
    super.didUpdateAttrs(...arguments);
    this.set("templatesLoaded", false);
    this.triggerSearch();
  }

  search(filter) {
    if (this.get("templatesLoaded")) {
      return super.search(filter);
    } else {
      return this._fetchTemplates();
    }
  }

  async _fetchTemplates() {
    if (this.get("loadingTemplates")) {
      return;
    }

    this.set("templatesLoaded", false);
    this.set("loadingTemplates", true);

    const result = await FormTemplate.findAll();

    if (this.isDestroying) {
      return;
    }

    let sortedTemplates = this._sortTemplatesByName(result);

    if (this.filteredIds) {
      sortedTemplates = sortedTemplates.filter((t) =>
        this.filteredIds.includes(t.id)
      );
    }

    if (sortedTemplates.length === 0) {
      this.set("selectKit.options.disabled", true);
    }

    this.setProperties({
      templates: sortedTemplates,
      loadingTemplates: false,
      templatesLoaded: true,
    });

    return this.templates;
  }

  _sortTemplatesByName(templates) {
    return templates.sort((a, b) => a.name.localeCompare(b.name));
  }
}
/**
   lock scroll of an element using overflow:hidden
   preserve gutter with scroll detection
*/
function lockScroll(element) {
  element ??= document.scrollingElement;
  if (!element) {
    return;
  }

  let scrollGap;

  //Add scroll gap if using default scrolling element
  if (element === document.scrollingElement) {
    scrollGap = Math.max(0, window.innerWidth - element.clientWidth);
  } else {
    scrollGap = element.offsetWidth - element.clientWidth;
  }
  element.style.setProperty("--scroll-gap", `${scrollGap}px`);
  element.classList.add("scroll-lock");
}

function unlockScroll(element) {
  element ??= document.scrollingElement;
  if (!element) {
    return;
  }

  element.classList.remove("scroll-lock");
  element.style.setProperty("--scroll-gap", null);
}

export default function scrollLock(lock, element = document.scrollingElement) {
  if (lock) {
    lockScroll(element);
  } else {
    unlockScroll(element);
  }
}
import { scheduleOnce } from "@ember/runloop";
import { isTesting } from "discourse/lib/environment";
import DiscourseURL from "discourse/lib/url";

const context = {
  _scrollTop() {
    if (isTesting()) {
      return;
    }
    document.documentElement.scrollTop = 0;
  },
};

function scrollTop() {
  if (DiscourseURL.isJumpScheduled()) {
    return;
  }
  scheduleOnce("afterRender", context, context._scrollTop);
}

