export function step<T>(
  index: number,
  delta: 1 | -1,
  cells: T[],
  columns: number,
  orientation: Orientation,
  wrap: boolean,
  isNavigable: (item: T) => boolean
): StepOutcome {
  const last = cells.length - 1;
  if (index < 0) {
    const seed = scan(cells, delta > 0 ? 0 : last, delta, 0, last, isNavigable);
    return seed == null
      ? { kind: "group-edge" }
