        </dropdown.item>
      {{/if}}
      {{#if this.canMoveUp}}
        <dropdown.item role="none">
          <MoveItem
            @icon="arrow-up"
            @label={{i18n "reorder.move_up"}}
            @move={{fn this.move "up"}}
            @target="up"
          />
        </dropdown.item>
      {{/if}}
      {{#if this.canMoveDown}}
        <dropdown.item role="none">
          <MoveItem
            @icon="arrow-down"
            @label={{i18n "reorder.move_down"}}
            @move={{fn this.move "down"}}
            @target="down"
