    }

    if (this.openKey === key) {
      await this.closeMenu();
      return;
    }

    const row = this.#rowFor(key);
    if (
      row &&
      !row.canMoveUp &&
      !row.canMoveDown &&
      this.#siblings().length === 0 &&
      !this.#canSpill("up") &&
