export default class MoveEngine<T> {
  #args: () => MoveEngineArgs<T>;
  #rows: () => Row<T>[];
  #listId: () => string;
  #announcer: ReorderAnnouncer<T>;
  #refocusIndex: (index: number) => void;

  constructor({
    args,
    rows,
    listId,
    announcer,
    refocusIndex,
  }: MoveEngineOptions<T>) {
    this.#args = args;
